== common
{"$schema": "https://json-schema.org/draft/2020-12/schema", "$id": "https://aircoin.example/schemas/v1/common.schema.json", "title": "AIRcoin shared definitions (v1)", "description": "Types reused by C1-C4, the miner/sticker registry and the species catalogue. Not a message on its own.", "$defs": {"schema_version": {"description": "Major version of the interface contract this message follows. Frozen at 1 at Gate 1.", "const": 1}, "miner_id": {"description": "Human-readable miner ID, also used in MQTT topics (miner/{miner_id}/...). On-chain the miner is keyed by keccak256(utf8(miner_id)).", "type": "string", "pattern": "^[a-z0-9][a-z0-9-]{2,63}$", "examples": ["miner-001"]}, "timestamp_ms": {"description": "Unix time in milliseconds, UTC.", "type": "integer", "minimum": 0}, "epoch": {"description": "Epoch index = floor(start_ms / epoch_length_ms). Epoch length is 60 000 ms for the demo (1 h in production), so every miner and the validator agree on boundaries.", "type": "integer", "minimum": 0}, "tag_id": {"description": "ArUco marker ID printed on a plant sticker. Globally unique: each ID is registered to exactly one miner.", "type": "integer", "minimum": 0, "maximum": 999}, "species_id": {"description": "Species from the fixed list of 20 (PRD 2.3). Display names, coefficients etc. live in data/species-catalogue.json.", "type": "string", "enum": ["snake_plant", "peace_lily", "bamboo_palm", "red_edged_dracaena", "janet_craig_dracaena", "english_ivy", "chinese_evergreen", "florists_chrysanthemum", "weeping_fig", "money_plant", "spider_plant", "aloe_vera", "areca_palm", "boston_fern", "tulsi", "hibiscus", "neem", "shisham", "bougainvillea", "yellow_oleander"]}, "species_id_or_unknown": {"anyOf": [{"$ref": "#/$defs/species_id"}, {"const": "unknown"}]}, "pollutant": {"description": "Pollutant keys used everywhere a per-pollutant value appears. Weights are defined in the species catalogue (PRD 2.6).", "type": "string", "enum": ["pm25", "pm10", "no2", "so2", "voc", "co2", "co"]}, "per_pollutant_mg": {"description": "Milligrams removed, keyed by pollutant. Missing keys mean 0.", "type": "object", "propertyNames": {"$ref": "#/$defs/pollutant"}, "additionalProperties": {"type": "number", "minimum": 0}}, "plant_status": {"description": "Vision status machine (PRD 7.1 #7): present -> missing after 10 s unseen -> removed after 60 s unseen; suspect when the plant match or alive_score is low.", "type": "string", "enum": ["present", "missing", "removed", "suspect"]}, "eth_address": {"description": "EIP-55 or lowercase 0x-prefixed 20-byte address.", "type": "string", "pattern": "^0x[0-9a-fA-F]{40}$"}, "bytes32_hex": {"description": "0x-prefixed 32-byte hex string (keccak256 / sha256 digest).", "type": "string", "pattern": "^0x[0-9a-fA-F]{64}$"}, "signature_hex": {"description": "0x-prefixed 65-byte secp256k1 signature (r || s || v), Ethereum style.", "type": "string", "pattern": "^0x[0-9a-fA-F]{130}$"}, "tx_hash": {"$ref": "#/$defs/bytes32_hex"}, "token_amount": {"description": "Token amount in base units as a decimal integer string (AIR and tINR use 18 decimals, so 1 AIR = \"1000000000000000000\"). Strings avoid float rounding.", "type": "string", "pattern": "^(0|[1-9][0-9]*)$"}, "gps": {"description": "Location fix. fix = 'fallback' means no satellite fix and the configured demo location is reported instead.", "type": "object", "required": ["lat", "lon", "fix"], "properties": {"lat": {"type": "number", "minimum": -90, "maximum": 90}, "lon": {"type": "number", "minimum": -180, "maximum": 180}, "alt_m": {"type": "number"}, "fix": {"type": "string", "enum": ["none", "2d", "3d", "fallback"]}, "hdop": {"type": "number", "minimum": 0}, "satellites": {"type": "integer", "minimum": 0}, "ts": {"$ref": "#/$defs/timestamp_ms"}}, "additionalProperties": false}, "sensor_readings": {"description": "One snapshot of the (simulated) air sensors. Units are in the key names.", "type": "object", "required": ["pm25_ugm3", "pm10_ugm3", "co2_ppm", "voc_index", "no2_ppb", "temp_c", "humidity_pct"], "properties": {"pm25_ugm3": {"type": "number", "minimum": 0}, "pm10_ugm3": {"type": "number", "minimum": 0}, "co2_ppm": {"type": "number", "minimum": 0}, "voc_index": {"description": "Sensirion-style VOC index, 0-500 (100 = typical).", "type": "number", "minimum": 0, "maximum": 500}, "no2_ppb": {"type": "number", "minimum": 0}, "so2_ppb": {"type": "number", "minimum": 0}, "co_ppm": {"type": "number", "minimum": 0}, "temp_c": {"type": "number", "minimum": -40, "m

== c2-telemetry
{"$schema": "https://json-schema.org/draft/2020-12/schema", "$id": "https://aircoin.example/schemas/v1/c2-telemetry.schema.json", "title": "C2 \u00c2\u00b7 Live telemetry (B -> A, C)", "description": "Published by miner-core on MQTT topic miner/{miner_id}/telemetry once per second (QoS 0). Everything the twin and the admin portal need to draw the live state of one miner.", "type": "object", "required": ["v", "miner_id", "ts", "sensors", "gps", "plants", "current_epoch", "flags"], "properties": {"v": {"$ref": "common.schema.json#/$defs/schema_version"}, "miner_id": {"$ref": "common.schema.json#/$defs/miner_id"}, "ts": {"$ref": "common.schema.json#/$defs/timestamp_ms"}, "scenario": {"description": "Active sensor-simulator scenario (free text so B can add scenarios without a contract change).", "type": "string", "examples": ["clean_morning", "rush_hour", "festival_smog", "rain_washout"]}, "sensors_simulated": {"description": "True when air sensor values come from the simulator.", "type": "boolean"}, "aqi": {"description": "Current AQI (0-500) derived from the sensors.", "type": "number", "minimum": 0, "maximum": 500}, "sensors": {"$ref": "common.schema.json#/$defs/sensor_readings"}, "gps": {"$ref": "common.schema.json#/$defs/gps"}, "plants": {"description": "Latest known state of each plant (from C1) plus its current estimated removal rate.", "type": "array", "maxItems": 20, "items": {"type": "object", "required": ["tag_id", "species", "status", "leaf_area_cm2", "alive_score", "rate_air_per_h"], "properties": {"tag_id": {"$ref": "common.schema.json#/$defs/tag_id"}, "species": {"$ref": "common.schema.json#/$defs/species_id_or_unknown"}, "status": {"$ref": "common.schema.json#/$defs/plant_status"}, "leaf_area_cm2": {"type": "number", "minimum": 0}, "alive_score": {"type": "number", "minimum": 0, "maximum": 1}, "species_conf": {"type": "number", "minimum": 0, "maximum": 1}, "rate_air_per_h": {"description": "Current estimated earning rate for this plant in AIR per hour (display only). 0 for missing/removed/suspect plants.", "type": "number", "minimum": 0}}, "additionalProperties": false}}, "current_epoch": {"description": "Progress of the epoch in flight.", "type": "object", "required": ["epoch", "start_ms", "end_ms", "running_air"], "properties": {"epoch": {"$ref": "common.schema.json#/$defs/epoch"}, "start_ms": {"$ref": "common.schema.json#/$defs/timestamp_ms"}, "end_ms": {"$ref": "common.schema.json#/$defs/timestamp_ms"}, "running_air": {"description": "AIR estimated so far in this epoch (display only; the epoch message is authoritative).", "type": "number", "minimum": 0}}, "additionalProperties": false}, "flags": {"description": "Anti-cheat flags currently active.", "type": "array", "items": {"$ref": "common.schema.json#/$defs/anticheat_flag"}}, "uplink": {"description": "Health of the miner -> validator link.", "type": "object", "properties": {"online": {"type": "boolean"}, "queued_attestations": {"type": "integer", "minimum": 0}}, "additionalProperties": false}, "device": {"description": "Optional Pi health for the 3D model's exploded view.", "type": "object", "properties": {"cpu_temp_c": {"type": "number"}, "cpu_pct": {"type": "number", "minimum": 0, "maximum": 100}, "mem_pct": {"type": "number", "minimum": 0, "maximum": 100}, "uptime_s": {"type": "integer", "minimum": 0}}, "additionalProperties": false}}, "additionalProperties": false}

== c2-epoch
{"$schema": "https://json-schema.org/draft/2020-12/schema", "$id": "https://aircoin.example/schemas/v1/c2-epoch.schema.json", "title": "C2 \u00c2\u00b7 Epoch summary (B -> A, C)", "description": "Published by miner-core on MQTT topic miner/{miner_id}/epoch (QoS 1, retained) when an epoch closes, and re-published for the same epoch whenever its attestation status changes (pending -> submitted -> accepted/rejected).", "type": "object", "required": ["v", "miner_id", "epoch", "start_ms", "end_ms", "plants", "by_pollutant_mg", "total_air", "attestation", "flags"], "properties": {"v": {"$ref": "common.schema.json#/$defs/schema_version"}, "miner_id": {"$ref": "common.schema.json#/$defs/miner_id"}, "epoch": {"$ref": "common.schema.json#/$defs/epoch"}, "start_ms": {"$ref": "common.schema.json#/$defs/timestamp_ms"}, "end_ms": {"$ref": "common.schema.json#/$defs/timestamp_ms"}, "scenario": {"type": "string"}, "sensor_summary": {"$ref": "common.schema.json#/$defs/sensor_summary"}, "plants": {"description": "Per-plant estimate for the epoch (PRD 2.5 model R_i,p).", "type": "array", "maxItems": 20, "items": {"type": "object", "required": ["tag_id", "species", "status", "removed_mg", "air"], "properties": {"tag_id": {"$ref": "common.schema.json#/$defs/tag_id"}, "species": {"$ref": "common.schema.json#/$defs/species_id_or_unknown"}, "status": {"$ref": "common.schema.json#/$defs/plant_status"}, "leaf_area_cm2": {"type": "number", "minimum": 0}, "health": {"type": "number", "minimum": 0, "maximum": 1}, "removed_mg": {"$ref": "common.schema.json#/$defs/per_pollutant_mg"}, "air": {"description": "Weighted AIR for this plant this epoch (sum_p w_p * R_i,p).", "type": "number", "minimum": 0}}, "additionalProperties": false}}, "by_pollutant_mg": {"description": "Total removed per pollutant across all plants (drives the per-pollutant breakdown on stage).", "$ref": "common.schema.json#/$defs/per_pollutant_mg"}, "total_air": {"description": "Epoch total in AIR (decimal, display). The attestation's amount is the authoritative base-unit value.", "type": "number", "minimum": 0}, "attestation": {"type": "object", "required": ["status"], "properties": {"status": {"$ref": "common.schema.json#/$defs/attestation_status"}, "evidence_hash": {"$ref": "common.schema.json#/$defs/bytes32_hex"}, "amount": {"$ref": "common.schema.json#/$defs/token_amount"}, "tx_hash": {"$ref": "common.schema.json#/$defs/tx_hash"}, "reason_code": {"$ref": "common.schema.json#/$defs/rejection_reason_code"}, "reason": {"type": "string"}}, "additionalProperties": false}, "flags": {"description": "Anti-cheat flags raised during this epoch.", "type": "array", "items": {"$ref": "common.schema.json#/$defs/anticheat_flag"}}}, "additionalProperties": false}

== c3-attestation
{"$schema": "https://json-schema.org/draft/2020-12/schema", "$id": "https://aircoin.example/schemas/v1/c3-attestation.schema.json", "title": "C3 \u00c2\u00b7 Signed attestation (B -> C)", "description": "Request body of HTTPS POST /v1/attestations, sent by miner-core once per closed epoch (retried from an offline queue). See contracts-schema/README.md for how evidence_hash and signature are computed.", "type": "object", "required": ["v", "miner_id", "epoch", "start", "end", "gps", "sensor_summary", "plants", "amount", "calibration_hash", "evidence_hash", "signature"], "properties": {"v": {"$ref": "common.schema.json#/$defs/schema_version"}, "miner_id": {"$ref": "common.schema.json#/$defs/miner_id"}, "epoch": {"$ref": "common.schema.json#/$defs/epoch"}, "start": {"description": "Epoch start, Unix ms. Must equal epoch * epoch_length_ms.", "$ref": "common.schema.json#/$defs/timestamp_ms"}, "end": {"description": "Epoch end, Unix ms (exclusive).", "$ref": "common.schema.json#/$defs/timestamp_ms"}, "gps": {"$ref": "common.schema.json#/$defs/gps"}, "sensor_summary": {"$ref": "common.schema.json#/$defs/sensor_summary"}, "plants": {"description": "Plant states for the epoch. Every tag_id must belong to this miner's registered sticker set.", "type": "array", "maxItems": 20, "items": {"type": "object", "required": ["tag_id", "species", "status", "leaf_area_cm2", "health", "removed_mg", "air"], "properties": {"tag_id": {"$ref": "common.schema.json#/$defs/tag_id"}, "species": {"$ref": "common.schema.json#/$defs/species_id_or_unknown"}, "status": {"$ref": "common.schema.json#/$defs/plant_status"}, "leaf_area_cm2": {"type": "number", "minimum": 0}, "health": {"type": "number", "minimum": 0, "maximum": 1}, "removed_mg": {"$ref": "common.schema.json#/$defs/per_pollutant_mg"}, "air": {"type": "number", "minimum": 0}}, "additionalProperties": false}}, "frame_hashes": {"description": "sha256 of the frames used this epoch (from C1). Included so the validator can recompute evidence_hash.", "type": "array", "items": {"$ref": "common.schema.json#/$defs/bytes32_hex"}}, "flags": {"description": "Device-side anti-cheat flags raised this epoch (informational for the validator and admin portal).", "type": "array", "items": {"$ref": "common.schema.json#/$defs/anticheat_flag"}}, "amount": {"description": "Claimed AIR for the epoch in base units (18 decimals). This exact value is signed and minted.", "$ref": "common.schema.json#/$defs/token_amount"}, "calibration_hash": {"description": "keccak256 of the canonical species-catalogue JSON used for the estimate (PRD 8.1 #5).", "$ref": "common.schema.json#/$defs/bytes32_hex"}, "evidence_hash": {"$ref": "common.schema.json#/$defs/bytes32_hex"}, "signature": {"description": "Device-key secp256k1 signature over the mint digest (README: Signing).", "$ref": "common.schema.json#/$defs/signature_hex"}}, "additionalProperties": false}
